// Erkundet /v2/invoice/list: Statuscode, Satzzahl, Huellenfelder und
// Feldbestand je Rechnung. Zeigt Klarwerte nur bei steuerlich
// bedeutsamen Feldern, sonst nur Werttypen.

const auth = $('S22 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abrufen(qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://app1.edoobox.com/v2/invoice/list',
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abrufen.bind(this);

// Erste Seite als Probe. 500 Saetze genuegen fuer den Feldbestand.
const erste = await hole({ 'limit[start]': 0, 'limit[reply]': 500 });

const zeilen = [];

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'statuscode',
    arten: String(erste.statusCode),
    beispielwerte: '',
  },
});

if (erste.statusCode !== 200) {
  zeilen.push({
    json: {
      schritt: 'S22',
      bereich: 'Antwort',
      feld: 'fehlertext',
      arten: String(erste.body && typeof erste.body === 'object'
        ? JSON.stringify(erste.body).slice(0, 300)
        : String(erste.body).slice(0, 300)),
      beispielwerte: '',
    },
  });
  return zeilen;
}

const huelle = erste.body && typeof erste.body === 'object' ? erste.body : {};

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'huellenfelder',
    arten: Object.keys(huelle).join(', '),
    beispielwerte: '',
  },
});

// Satzzahl aus allen plausiblen Stellen einsammeln.
for (const kandidat of ['total', 'count', 'amount', 'records', 'result', 'meta']) {
  if (huelle[kandidat] !== undefined && typeof huelle[kandidat] !== 'object') {
    zeilen.push({
      json: {
        schritt: 'S22',
        bereich: 'Antwort',
        feld: `huelle.${kandidat}`,
        arten: String(huelle[kandidat]),
        beispielwerte: '',
      },
    });
  }
}

const daten = Array.isArray(huelle.data)
  ? huelle.data
  : huelle.data && typeof huelle.data === 'object'
    ? Object.values(huelle.data)
    : [];

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'saetze auf erster seite',
    arten: String(daten.length),
    beispielwerte: '',
  },
});

function art(wert) {
  if (wert === null) return 'null';
  if (Array.isArray(wert)) return `liste[${wert.length}]`;
  if (typeof wert === 'object') return `objekt{${Object.keys(wert).slice(0, 12).join(',')}}`;
  if (typeof wert === 'boolean') return `wahrheitswert:${wert}`;
  if (typeof wert === 'number') return 'zahl';
  if (typeof wert === 'string') {
    if (wert === '') return 'text:leer';
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(wert)) return 'text:zeitpunkt';
    if (/^-?[0-9]+([.,][0-9]+)?$/.test(wert)) return 'text:zahl';
    return `text(${wert.length})`;
  }
  return typeof wert;
}

// Bei diesen Feldnamen sind Klarwerte unbedenklich und aufschlussreich.
const offen = /vat|ust|tax|steuer|mwst|currency|waehrung|status|type|art|country|land|state|paid|open|number|nummer|amount|betrag|total|net|gross|brutto|netto|date|datum|time|rate|satz|b2b|booking|offer|reverse|charge/i;

const uebersicht = new Map();

for (const r of daten) {
  if (!r || typeof r !== 'object') continue;
  for (const [feld, wert] of Object.entries(r)) {
    if (!uebersicht.has(feld)) uebersicht.set(feld, { feld, arten: new Set(), werte: new Set(), gefuellt: 0 });
    const e = uebersicht.get(feld);
    e.arten.add(art(wert));
    if (wert !== null && wert !== '' && wert !== false) e.gefuellt += 1;
    if (offen.test(feld) && (typeof wert !== 'object' || wert === null)) {
      const t = String(wert);
      if (t.length <= 28) e.werte.add(t);
    }
  }
}

for (const e of [...uebersicht.values()].sort((a, b) => a.feld.localeCompare(b.feld))) {
  zeilen.push({
    json: {
      schritt: 'S22',
      bereich: 'Rechnung',
      feld: e.feld,
      arten: `${[...e.arten].slice(0, 4).join(' | ')}  (gefuellt ${e.gefuellt}/${daten.length})`,
      beispielwerte: [...e.werte].slice(0, 8).join(' | '),
    },
  });
}

// Gesamtzahl durch Blaettern bestimmen, falls die Huelle sie nicht nennt.
let gesamt = daten.length;
let abrufe = 1;

if (daten.length === 500) {
  let start = 500;
  while (abrufe < 30) {
    const w = await hole({ 'limit[start]': start, 'limit[reply]': 2000 });
    abrufe += 1;
    if (w.statusCode !== 200) break;
    const h = w.body && typeof w.body === 'object' ? w.body : {};
    const d = Array.isArray(h.data) ? h.data : h.data && typeof h.data === 'object' ? Object.values(h.data) : [];
    gesamt += d.length;
    if (d.length < 2000) break;
    start += 2000;
  }
}

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'rechnungen gesamt',
    arten: `${gesamt} bei ${abrufe} Abrufen`,
    beispielwerte: '',
  },
});

return zeilen;
